/** BIP-39 test mnemonics (the Kaspa set) — never fund them. */
export const MNEMONIC_W =
  'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';
export const MNEMONIC_KK =
  'legal winner thank year wave sausage worth useful legal winner thank yellow';
export const MNEMONIC_S3 =
  'letter advice cage absurd amount doctor acoustic avoid letter advice cage above';
export const MNEMONIC_Z = 'zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo wrong';

export const TRON = 'tron';

/** The fee collector the vector Op pays (a fixed test address). */
export const VECTOR_FEE_COLLECTOR = 'TFhcYVArFkJW6bPUDid4AFCAjKmh6Ez3vv';
/** The vector Op's recipient. */
export const VECTOR_RECIPIENT = 'TGjtodRV2nm6tQd9hsxiecLNN9QmhhVbbD';
/** A fixed test sponsor label (only its presence matters to isTronLive). */
export const VECTOR_SPONSOR = T.addressFromBytes20(
  new Uint8Array(20).fill(0x55),
);

/**
 * The explicit NetworkConfig the vectors were generated with: mainnet's
 * chainId + USDT and the fixed factory / implementation test labels, plus the
 * vector fee collector (and a sponsor label) so the network counts as live.
 */
export const VECTOR_NETWORK: T.NetworkConfig = T.getNetwork({
  ...T.NETWORKS.mainnet,
  name: 'ssp-vectors',
  factory: TRON_VECTORS.network.factory,
  implementation: TRON_VECTORS.network.implementation,
  sponsor: VECTOR_SPONSOR,
  feeCollector: VECTOR_FEE_COLLECTOR,
});

/** Vector time: 30 minutes before the vector Op's deadline (1790000000). */
export const VECTOR_NOW = 1790000000n - 1800n;

export function tronXpub(mnemonic: string, account: number): string {
  return getMasterXpub(mnemonic, 48, 195, account, 'p2sh', TRON);
}

export function tronXpriv(mnemonic: string, account: number): string {
  return getMasterXpriv(mnemonic, 48, 195, account, 'p2sh', TRON);
}

/** The raw leaf private key m/48'/195'/{account}'/0'/a/b of a test mnemonic. */
export function leafPriv(
  mnemonic: string,
  account: number,
  a: number,
  b: number,
) {
  const node = HDKey.fromExtendedKey(
    tronXpriv(mnemonic, account),
    blockchains[TRON].bip32,
  )
    .deriveChild(a)
    .deriveChild(b);
  return node.privateKey as Uint8Array;
}

/** A consumer payload for leaf 0-i, signed by the WALLET (mnemonic W). */
export function consumerPayload(
  op: T.Op,
  overrides: Record<string, unknown> = {},
  opts: { addressIndex?: number; signWith?: Uint8Array } = {},
): string {
  const i = opts.addressIndex ?? 0;
  const own = tronConsumerVault(
    TRON_VECTORS.consumer.walletXpub,
    TRON_VECTORS.consumer.keyXpub,
    0,
    i,
    TRON,
    VECTOR_NETWORK,
  );
  const digest = T.opDigest(VECTOR_NETWORK.chainId, own.vault.address, op);
  const signer = T.localSigner(opts.signWith ?? leafPriv(MNEMONIC_W, 0, 0, i));
  const walletSignature = T.to0x(signer.signDigest(digest));
  signer.destroy();
  return JSON.stringify({
    format: 'ssp-tron-op',
    version: 1,
    network: 'ssp-vectors',
    vault: own.vault.address,
    signers: own.config.signers,
    threshold: own.config.threshold,
    op: T.opToJson(op),
    walletSignature,
    ...overrides,
  });
}
